def rule_full_text_budget_sentence(doc: dict) -> list[dict]:
    try:
        import re

        text = doc.get("text") or ""
        if not text:
            return []

        spans: list[dict] = []
        seen = set()

        def compact(s: str) -> str:
            return "".join(ch for ch in s.lower() if ch.isalnum())

        patterns = [
            re.compile(
                r"(?i)(?:fiscal(?: year)?\s*\d{2,4}[^.:\n]{0,220}?\b\d+(?:\.\d+)?\s*(?:%|percent|per cent)\s*(?:of|in relation to|relative to|as a share of|share of)?\s*(?:gdp|gnp|nominal gdp|gross national product)\b[^.\n]{0,200})"
            ),
            re.compile(
                r"(?i)(?:\b\d+(?:\.\d+)?\s*(?:%|percent|per cent)\s*(?:of|in relation to|relative to|as a share of|share of)?\s*(?:gdp|gnp|nominal gdp|gross national product)\b[^.\n]{0,200})"
            ),
            re.compile(
                r"(?i)(?:\b(?:gdp|gnp|nominal gdp|gross national product)\b[^.\n]{0,200}?\b\d+(?:\.\d+)?\s*(?:%|percent|per cent)\b)"
            ),
        ]

        for pat in patterns:
            for m in pat.finditer(text):
                phrase = m.group(0).strip()
                start = max(0, text.rfind("\n", 0, m.start()) + 1)
                left_period = text.rfind(".", 0, m.start())
                left_nl = text.rfind("\n", 0, m.start())
                start = max(start, left_period + 1 if left_period != -1 else 0, left_nl + 1 if left_nl != -1 else 0)
                end_candidates = [
                    text.find(".", m.end()),
                    text.find("\n", m.end()),
                ]
                end_candidates = [x for x in end_candidates if x != -1]
                end = min(end_candidates) if end_candidates else min(len(text), m.end() + 240)
                snippet = text[start:end].strip()
                for candidate in (phrase, snippet):
                    if not candidate:
                        continue
                    low = candidate.lower()
                    ctext = compact(candidate)
                    if not any(term in low or term in ctext for term in ("fiscal", "fy", "budget", "deficit", "surplus", "receipts", "outlays")):
                        continue
                    key = (candidate,)
                    if key in seen:
                        continue
                    seen.add(key)
                    spans.append({"text": candidate})

        return spans
    except Exception:
        return []

def rule_budget_year_percent(doc: dict) -> list[dict]:
    try:
        import re

        spans: list[dict] = []
        seen = set()
        paragraphs = doc.get("paragraphs") or []

        def compact(s: str) -> str:
            return re.sub(r"[^a-z0-9.]+", "", s.lower())

        percent_re = re.compile(
            r"(?i)\b\d+(?:\.\d+)?\s*(?:%|percent|per cent)\s*(?:of|as a share of|share of|in relation to|relative to)?\s*(?:gdp|gnp|nominal gdp|gross national product)\b"
        )
        year_re = re.compile(r"(?i)\b(?:fy|fiscal(?: year)?)\s*\d{2,4}\b")

        for para in paragraphs:
            text = (para.get("text") or "").strip()
            low = text.lower()
            ctext = compact(text)
            if not text:
                continue
            if not percent_re.search(text) and not re.search(
                r"\b\d+(?:\.\d+)?(?:%|percent|percentof|percentinrelationto|per cent)\b.*\b(?:gdp|gnp|nominalgdp|grossnationalproduct)\b",
                ctext,
            ):
                continue
            if not year_re.search(text) and "fiscal" not in low and "fy" not in low:
                continue
            if not any(
                term in low or term.replace(" ", "") in ctext
                for term in (
                    "budget",
                    "deficit",
                    "surplus",
                    "outlays",
                    "receipts",
                    "federal budget",
                    "federal deficit",
                    "federal outlays",
                    "federal receipts",
                )
            ):
                continue
            key = (
                para.get("page_no"),
                para.get("paragraph_no"),
                text,
            )
            if key in seen:
                continue
            seen.add(key)
            spans.append({k: v for k, v in para.items() if k in {"page_no", "paragraph_no", "text"}})

        return spans
    except Exception:
        return []

