  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54mini/all_docs/q08_what_was_the_total_surplus_or_deficit_for_the_fiscal_year_to/rule_ffo1_total_surplus_or_deficit_paragraph.py",
  "code": "import re\n\n\ndef rule_ffo1_total_surplus_or_deficit_paragraph(doc: dict) -> list[dict]:\n    try:\n        paragraphs = doc.get(\"paragraphs\") or []\n        if not paragraphs:\n            return []\n\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").strip()).lower()\n\n        def clean_text(text: str) -> str:\n            return (text or \"\").replace(\"−\", \"-\").replace(\"--\", \"-\")\n\n        def extract_signed_numbers(text: str) -> list[str]:\n            return re.findall(r\"-?\\d[\\d,]*\", clean_text(text))\n\n        def make_span(para: dict, text: str) -> dict:\n            span = {\"text\": text}\n            if para.get(\"page_no\") is not None:\n                span[\"page_no\"] = para.get(\"page_no\")\n            if para.get(\"paragraph_no\") is not None:\n                span[\"paragraph_no\"] = para.get(\"paragraph_no\")\n            return span\n\n        for idx, para in enumerate(paragraphs):\n            text = (para.get(\"text\") or \"\").strip()\n            low = norm(text)\n            if not text:\n                continue\n            if \"total surplus or deficit\" not in low:\n                continue\n            if \"on-budget\" in low or \"off-budget\" in low:\n                continue\n\n            window_parts = [text]\n            for j in range(idx + 1, min(len(paragraphs), idx + 3)):\n                nxt = (paragraphs[j].get(\"text\") or \"\").strip()\n                if nxt:\n                    window_parts.append(nxt)\n            window = \" \".join(window_parts)\n            nums = extract_signed_numbers(window)\n            if not nums:\n                continue\n            answer = nums[-1]\n            return [make_span(para, answer)]\n\n        return []\n    except Exception:\n        return []\n",
