{
  "rule_name": "rule_ffo1_total_surplus_or_deficit_table",
  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54mini/all_docs/q08_what_was_the_total_surplus_or_deficit_for_the_fiscal_year_to/rule_ffo1_total_surplus_or_deficit_table.py",
  "code": "import re\n\n\ndef rule_ffo1_total_surplus_or_deficit_table(doc: dict) -> list[dict]:\n    try:\n        lines = doc.get(\"lines\") or []\n        if not lines:\n            return []\n\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").strip()).lower()\n\n        def clean_text(text: str) -> str:\n            return (text or \"\").replace(\"−\", \"-\").replace(\"--\", \"-\")\n\n        def extract_signed_numbers(text: str) -> list[str]:\n            return re.findall(r\"-?\\d[\\d,]*\", clean_text(text))\n\n        def make_span_from_line(text: str, line: dict) -> dict:\n            span = {\"text\": text}\n            if line.get(\"page_no\") is not None:\n                span[\"page_no\"] = line.get(\"page_no\")\n            if line.get(\"line_no\") is not None:\n                span[\"line_no\"] = line.get(\"line_no\")\n            return span\n\n        heading_idx = None\n        for idx, line in enumerate(lines):\n            low = norm(line.get(\"text\") or \"\")\n            if \"table ffo-1\" in low and \"summary of fiscal operations\" in low:\n                heading_idx = idx\n                break\n        if heading_idx is None:\n            for idx, line in enumerate(lines):\n                low = norm(line.get(\"text\") or \"\")\n                if \"summary of fiscal operations\" in low and \"fiscal year or month\" in low:\n                    heading_idx = idx\n                    break\n        if heading_idx is None:\n            return []\n\n        search_limit = min(len(lines), heading_idx + 1000)\n        for idx in range(heading_idx, search_limit):\n            low = norm(lines[idx].get(\"text\") or \"\")\n            if \"total surplus or deficit\" not in low:\n                continue\n            if \"on-budget\" in low or \"off-budget\" in low:\n                continue\n\n            collected: list[tuple[int, str]] = []\n            for j in range(idx, min(len(lines), idx + 5)):\n                raw = lines[j].get(\"text\") or \"\"\n                nums = extract_signed_numbers(raw)\n                if not nums:\n                    continue\n                for num in nums:\n                    collected.append((j, num))\n                if len(collected) >= 2:\n                    break\n            if not collected:\n                continue\n\n            answer_idx, answer = collected[-1]\n            answer_line = lines[answer_idx]\n            return [make_span_from_line(answer, answer_line)]\n\n        return []\n    except Exception:\n        return []\n",
